import React, { useState, useRef } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [original, setOriginal] = useState(null);
  const [processed, setProcessed] = useState(null);
  const [accuracy, setAccuracy] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const fileRef = useRef();

  const handleFile = e => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = ev => {
      setOriginal(ev.target.result);
      setProcessed(null);
      setAccuracy(null);
      setError(null);
    };
    r.readAsDataURL(f);
  };

  const processImage = async () => {
    try {
      setLoading(true);
      const blob = await fetch(original).then(r => r.blob());
      const fd = new FormData();
      fd.append('image', blob, 'image.png');
      fd.append('colorblind_type', colorblindType);
      fd.append('mode', mode);

      const res = await axios.post(`${API_URL}/process-image`, fd);
      setProcessed(`data:image/png;base64,${res.data.processed_image}`);
      setAccuracy(res.data.accuracy);
    } catch (e) {
      setError(e.response?.data?.error || 'Processing failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <div className="upload-area" onClick={() => fileRef.current.click()}>
        <input type="file" ref={fileRef} accept="image/*" onChange={handleFile} hidden />
        Click or drag and drop an image here
      </div>

      {error && <div className="error">{error}</div>}

      <div className="image-preview">
        {original && <img src={original} alt="original" />}
        {processed && (
          <>
            <img src={processed} alt="processed" />
            <p>Filter Accuracy: {accuracy}%</p>
          </>
        )}
      </div>

      <button onClick={processImage} disabled={!original || loading}>
        {loading ? 'Processing...' : 'Process Image'}
      </button>
    </div>
  );
};

export default ImageProcessor;
